import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.C8822HRV.js";const u=JSON.parse('{"title":"AI agents setup for sdd","description":"Connect sdd to one AI host — GitHub Copilot, Claude Code, Grok, Ollama, or Kilo Code — with a single init command.","frontmatter":{"title":"AI agents setup for sdd","description":"Connect sdd to one AI host — GitHub Copilot, Claude Code, Grok, Ollama, or Kilo Code — with a single init command.","head":[["meta",{"property":"og:title","content":"AI agents setup for sdd · sdd"}],["meta",{"property":"og:description","content":"Connect sdd to one AI host — GitHub Copilot, Claude Code, Grok, Ollama, or Kilo Code — with a single init command."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/guides/agents/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"AI agents setup for sdd · sdd"}],["meta",{"name":"twitter:description","content":"Connect sdd to one AI host — GitHub Copilot, Claude Code, Grok, Ollama, or Kilo Code — with a single init command."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/guides/agents/"}]]},"headers":[],"relativePath":"guides/agents.md","filePath":"guides/agents.md","lastUpdated":1793333434000}'),i={name:"guides/agents.md"};function d(n,e,l,r,h,p){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="set-up-your-ai" tabindex="-1">Set up your AI <a class="header-anchor" href="#set-up-your-ai" aria-label="Permalink to &quot;Set up your AI&quot;">​</a></h1><p>You only need <strong>one</strong> AI coding tool. <code>sdd</code> installs a few small files for that tool and keeps the real rules in one place.</p><blockquote><p>Your <strong>editor</strong> (VS Code, Cursor, …) is not the AI.<br> Your <strong>AI</strong> (Copilot, Grok, Claude, Ollama, or Kilo) is what writes with you.</p></blockquote><hr><h2 id="just-set-it-up-this-is-enough" tabindex="-1">Just set it up (this is enough) <a class="header-anchor" href="#just-set-it-up-this-is-enough" aria-label="Permalink to &quot;Just set it up (this is enough)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># In your app folder — pick ONE host, then press Enter through setup:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # GitHub Copilot, plus planner, architect, and builder</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sdd setup --ai grok</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sdd setup --ai claude</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sdd setup --ai ollama         # then: ollama pull llama3.2</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># sdd setup --ai kilo           # Kilo Code CLI</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My first change&quot;</span></span></code></pre></div><p><code>sdd setup --yes --ai copilot</code> writes the same host and the three duties without the questions.</p><p><code>sdd init --here --ai copilot</code> installs that same host when you want to choose the workflow with <code>sdd new</code> yourself.</p><p><code>sdd setup</code> also writes planner, architect, and builder when you have no roles yet. Those are the three duties: planning, architecture, and construction. Each one follows the stages of the workflow you name, and <code>sdd go</code> hands the next stage to the next role. <a href="./roles">Roles and duties</a> explains what they are, why that helps, and how to set up a software team instead.</p><p>That’s it for day one. The AI often opens after process commands so it can help with the current step.</p><p><strong>Learn without the AI opening?</strong> Add <code>--no-agent</code> (see <a href="./../tutorials/first-change">tutorial</a>).</p><p><strong>No AI host at all?</strong> Run <code>sdd setup --yes --no-agent</code>, or <code>sdd setup --no-agent</code> and press Enter. <code>sdd init --here --no-agent</code> is the same host-free folder. sdd installs no host files and no <code>AGENTS.md</code>, and nothing ever launches. <code>sdd doctor</code> treats this as a valid setup.</p><p><strong>Switch AI later:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><hr><h2 id="which-ai-should-i-pick" tabindex="-1">Which AI should I pick? <a class="header-anchor" href="#which-ai-should-i-pick" aria-label="Permalink to &quot;Which AI should I pick?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You already use…</th><th>Choose</th></tr></thead><tbody><tr><td>Copilot in VS Code / Cursor</td><td><code>copilot</code></td></tr><tr><td>Grok Build CLI</td><td><code>grok</code></td></tr><tr><td>Claude Code CLI</td><td><code>claude</code></td></tr><tr><td>Local models only</td><td><code>ollama</code></td></tr><tr><td>Kilo Code CLI</td><td><code>kilo</code></td></tr></tbody></table><p>Full host details: <a href="./../reference/agents">Available agents</a>.</p><hr><h2 id="what-happens-when-i-run-commands" tabindex="-1">What happens when I run commands? <a class="header-anchor" href="#what-happens-when-i-run-commands" aria-label="Permalink to &quot;What happens when I run commands?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>After this…</th><th>Does the AI open?</th></tr></thead><tbody><tr><td><code>sdd new</code>, <code>next</code>, <code>verify</code>, <code>complete</code>, <code>agent</code>, …</td><td><strong>Yes</strong> (unless <code>--no-agent</code>)</td></tr><tr><td><code>sdd status</code>, <code>doctor</code>, <code>workflows</code>, <code>backlog list</code></td><td><strong>No</strong></td></tr></tbody></table><table tabindex="0"><thead><tr><th>AI</th><th>How it runs</th></tr></thead><tbody><tr><td><strong>grok</strong> / <strong>claude</strong> / <strong>ollama</strong> / <strong>kilo</strong></td><td>Terminal launches the CLI</td></tr><tr><td><strong>copilot</strong></td><td>Open Copilot Chat → agent <code>sdd</code> (handoff file is refreshed)</td></tr></tbody></table><p>Skip the AI once: <code>--no-agent</code> or <code>SDD_NO_AGENT=1</code>.</p><hr><h2 id="where-do-the-rules-live" tabindex="-1">Where do the rules live? <a class="header-anchor" href="#where-do-the-rules-live" aria-label="Permalink to &quot;Where do the rules live?&quot;">​</a></h2><p>You don’t need to memorize this on day one.</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>.sdd/protocol.md</code></td><td>The one short playbook</td></tr><tr><td><code>.sdd/active-context.md</code></td><td>What you’re doing <em>right now</em></td></tr><tr><td><code>.sdd/handoff.md</code></td><td>Brief the AI just saw</td></tr><tr><td>Host folder (<code>.github/agents</code>, <code>.grok/rules</code>, …)</td><td>Tiny pointers to the playbook</td></tr></tbody></table><p><strong>One host at a time.</strong> Installing a new AI removes the other hosts’ sdd-generated stubs so you don’t get a mess of them. Files you wrote yourself, other tools’ files, and sdd files you edited are never overwritten or deleted. sdd lists them as kept.</p><hr><h2 id="optional-roles-copilot-claude" tabindex="-1">Optional: roles (Copilot / Claude) <a class="header-anchor" href="#optional-roles-copilot-claude" aria-label="Permalink to &quot;Optional: roles (Copilot / Claude)&quot;">​</a></h2><p>Some hosts get small role files (<code>sdd</code>, <code>sdd-planner</code>, <code>sdd-implementer</code>, <code>sdd-reviewer</code>).<br> They only say “read the live context, then the playbook.” Grok and Ollama use a single short brief instead.</p><hr><h2 id="a-product-team-is-a-different-set-of-files" tabindex="-1">A product team is a different set of files <a class="header-anchor" href="#a-product-team-is-a-different-set-of-files" aria-label="Permalink to &quot;A product team is a different set of files&quot;">​</a></h2><p>The host files above point an AI at the playbook. A product team is <code>.sdd/team.yaml</code> plus role files under <code>.sdd/roles/</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --template</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> software</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> team</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span></span></code></pre></div><p>Room and check commands are in the <a href="./everyday-loop">everyday loop</a> and the <a href="./../reference/cli">CLI reference</a>.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tutorials/first-change">Start in 10 minutes</a></li><li><a href="./everyday-loop">Everyday loop</a></li><li><a href="./../reference/agents">Available agents</a></li></ul>`,39)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
